---- MONITORS ----
------------------

-- See https://wiki.hypr.land/Configuring/Basics/Monitors/
hl.monitor({
    output   = "",
    mode     = "preferred",
    position = "auto",
    scale    = "auto",
})


---------------------
---- MY PROGRAMS ----
---------------------

-- Set programs that you use
local terminal = "foot"
local fileManager = "qs -c groma ipc call files toggle"  -- the shell's own Files window
local menu        = "qs -c groma ipc call launcher toggle"  -- the shell's own launcher


-------------------
---- AUTOSTART ----
-------------------

-- See https://wiki.hypr.land/Configuring/Basics/Autostart/

-- Autostart necessary processes (like notifications daemons, status bars, etc.)
-- Or execute your favorite apps at launch like this:
--
-- hl.on("hyprland.start", function () 
--   hl.exec_cmd(terminal)
--   hl.exec_cmd("nm-applet")
--   hl.exec_cmd("waybar & hyprpaper & firefox")
-- end)

-- Our Quickshell shell: the bar, the polkit authentication agent and the
-- notification daemon are all this one process, so the session needs it.
hl.on("hyprland.start", function ()
  hl.exec_cmd("qs -c groma")
end)


