-- See https://wiki.hypr.land/Configuring/Basics/Window-Rules/
-- and https://wiki.hypr.land/Configuring/Basics/Workspace-Rules/

-- Example window rules that are useful

local suppressMaximizeRule = hl.window_rule({
    -- Ignore maximize requests from all apps. You'll probably like this.
    name  = "suppress-maximize-events",
    match = { class = ".*" },

    suppress_event = "maximize",
})
-- suppressMaximizeRule:set_enabled(false)

hl.window_rule({
    -- Fix some dragging issues with XWayland
    name  = "fix-xwayland-drags",
    match = {
        class      = "^$",
        title      = "^$",
        xwayland   = true,
        float      = true,
        fullscreen = false,
        pin        = false,
    },

    no_focus = true,
})

-- Layer rules also return a handle.
-- local overlayLayerRule = hl.layer_rule({
--     name  = "no-anim-overlay",
--     match = { namespace = "^my-overlay$" },
--     no_anim = true,
-- })
-- overlayLayerRule:set_enabled(false)

-- Groma's own Files window: a pane of glass edge to edge, rounded by the
-- compositor, which also casts its shadow. 20 is Hyprland's ceiling, so
-- the design's 24 is 20 here and Theme.radiusWindow matches it - a pane
-- rounder than its window shows blurred corners. No border, since the
-- glass draws its own edge. Tiles like everything else; the layout is
-- anchored rather than fixed, so any size works. SUPER+V floats it.
hl.window_rule({
    name  = "groma-files",
    match = { class = "^org\\.quickshell$", title = "^Files$" },

    rounding    = 20,
    border_size = 0,
})

-- Groma Store is the same kind of window as Files.
hl.window_rule({
    name  = "groma-software",
    match = { class = "^org\\.quickshell$", title = "^Groma Store$" },

    rounding    = 20,
    border_size = 0,
})

-- What floats is a sheet: an app's "Save changes?", a file picker, a window
-- floated with SUPER+V. Same corners as Groma's own windows, and the glass
-- edge rather than the gradient - Theme.glassEdge, white at .32, which
-- system/gtk-3.0/gtk.css cannot draw itself: GTK 3 leaves the dialog's frame
-- to the compositor. GTK 3 dialogs carry no xdg-dialog hint to match on more
-- narrowly; floating is the only thing they all have in common.
hl.window_rule({
    name  = "groma-sheets",
    match = { float = true },

    rounding     = 20,
    border_size  = 1,
    border_color = "rgba(ffffff52)",
})

-- Hyprland-run windowrule
hl.window_rule({
    name  = "move-hyprland-run",
    match = { class = "hyprland-run" },

    move  = "20 monitor_h-120",
    float = true,
})


---------------------------------
---- MACHINE-LOCAL OVERRIDES ----
---------------------------------

-- Anything specific to one machine - a particular monitor layout, a keybind
-- you want on this laptop only - goes in ~/.config/hypr/machine.lua, which is
-- deliberately not part of this repository. See hypr/machine.lua.example.
--
-- require() resolves from ~/.config/hypr even though this file is a symlink
-- into the repo, so the override sits beside the symlink rather than in here.
-- pcall so a missing file is not an error: most machines will not need one.
pcall(require, "machine")
